INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (8, 'CRP-008', 'Legacy (<10.0)', 'pushed', 'pushed', 0, 'BackgroundModifier', 'Modernize BackgroundModifier Architecture via Dynamic Rainmeter Skin Engine', 'Revive and redesign BackgroundModifier modernization using a dynamic Rainmeter telemetry skin architecture, resolving previous development bottlenecks: 1) Replace brittle GDI+ bitmap wallpaper baking and cache-busting with live desktop widget overlay, 2) Dynamically generate multi-drive meter configurations from state.json (supporting 13+ drives), 3) Implement lightweight event-driven Rainmeter refresh signaling, 4) Ensure DPI scaling and icon-safe screen positioning.', 'Rolf', '2026-10-13 15:42:35', '2026-10-13 15:29:48', '', '', 'standard', 0, 1, '{"id": 8, "timestamp": "2026-10-13 15:42:35", "title": "Modernize BackgroundModifier Architecture via Dynamic Rainmeter Skin Engine", "origin_repo": "BackgroundModifier", "state": "pushed", "bundle_id": "unassigned", "author": "Rolf", "details": "Revive and redesign BackgroundModifier modernization using a dynamic Rainmeter telemetry skin architecture, resolving previous development bottlenecks: 1) Replace brittle GDI+ bitmap wallpaper baking and cache-busting with live desktop widget overlay, 2) Dynamically generate multi-drive meter configurations from state.json (supporting 13+ drives), 3) Implement lightweight event-driven Rainmeter refresh signaling, 4) Ensure DPI scaling and icon-safe screen positioning.", "plan_path": "LCM_Inventory/data/proposals/plans/Proposal-008_CR-2026-019_Plan.md", "walkthrough_path": "LCM_Inventory/data/proposals/plans/Proposal-008_CR-2026-019_Walkthrough.md", "progress_state": "pushed", "pushed_at": "2026-10-13 15:29:48", "dates": {"created": "2026-10-13 15:42:35", "suggested": "2026-10-13 15:42:35", "in_progress": "20