INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (47, 'CRP-047', 'Legacy (<10.0)', 'rejected', 'rejected', 0, '.agents/rules / LCM_AI', 'Formalize CRM (Change Request Management) as Named Acceptance Stage in LCM Lifecycle Chain', 'Add CRM (Change Request Management) as a named, formal stage in the LCM lifecycle chain, positioned between CRP and Implementation Plan. CRM represents management acceptance or rejection of the CRP - the governance approval gate. Currently implicit in the proposal state field but not named, documented, or expressed as a chain node. The proposal state field IS the CRM record. Update ProposalReviewFlowPolicy.md, the LCM lifecycle chain, and all related documentation to reflect CRM as a first-class lifecycle stage.', 'Rolf', '2026-10-13 18:52:00', '', '', '', 'standard', 0, 1, '{"id": 47, "timestamp": "2026-10-13 18:52:00", "title": "Formalize CRM (Change Request Management) as Named Acceptance Stage in LCM Lifecycle Chain", "origin_repo": ".agents/rules / LCM_AI", "state": "rejected", "bundle_id": "unassigned", "author": "Rolf", "details": "Add CRM (Change Request Management) as a named, formal stage in the LCM lifecycle chain, positioned between CRP and Implementation Plan. CRM represents management acceptance or rejection of the CRP - the governance approval gate. Currently implicit in the proposal state field but not named, documented, or expressed as a chain node. The proposal state field IS the CRM record. Update ProposalReviewFlowPolicy.md, the LCM lifecycle chain, and all related documentation to reflect CRM as a first-class lifecycle stage.", "plan_path": "", "walkthrough_path": "", "dates": {"created": "2026-10-13 18:52:00", "suggested": "2026-10-13 18:52:00", "rejected": "2026-10-13 18:02:08"}, "state_history": [{"state": "suggested", "timestamp": "2026-10-13 18:52:00", "user": "Rolf", "note": "Emerged from LCM-AI alignment discussion during disaster recovery session 2026-10-13"}, {"state": "rejected", "timestamp": "2026-10-13 18:02:08", "user": "Operator Directive / Backlog Reconciliation", "note": "Superseded / obsolete conceptual proposal rejected per operator directive."}], "crp_id": "CRP-047", "cr_id": "CRP-047", "progress_state": "rejected", "priority": 0, "lcm_version": "Legacy (<10.0)"}');
