INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (49, 'CRP-049', 'Legacy (<10.0)', 'rejected', 'rejected', 0, '.agents/rules / LCM_AI', 'Tiered Governance Model (T0-T3) - Event-Proportional Review Ceremony', 'Introduce formal T0-T3 event-proportional governance tiers to replace uniform ceremony. T0=Emergency/crash recovery (act first, register BUG post-hoc, BC5 waived or abbreviated). T1=Trivial (single-point fix, minimal CRP, lightweight BC5). T2=Standard (normal feature/defect, full CRP+plan+BC5+test, default). T3=Architectural (cross-repo design decisions, full chain including Architecture/Requirements docs, multi-pass BC5). Tier set explicitly by operator when issuing do #n; default is T2. Update ProposalReviewFlowPolicy.md.', 'Rolf', '2026-10-13 18:52:00', '', '', '', 'standard', 0, 1, '{"id": 49, "timestamp": "2026-10-13 18:52:00", "title": "Tiered Governance Model (T0-T3) - Event-Proportional Review Ceremony", "origin_repo": ".agents/rules / LCM_AI", "state": "rejected", "bundle_id": "unassigned", "author": "Rolf", "details": "Introduce formal T0-T3 event-proportional governance tiers to replace uniform ceremony. T0=Emergency/crash recovery (act first, register BUG post-hoc, BC5 waived or abbreviated). T1=Trivial (single-point fix, minimal CRP, lightweight BC5). T2=Standard (normal feature/defect, full CRP+plan+BC5+test, default). T3=Architectural (cross-repo design decisions, full chain including Architecture/Requirements docs, multi-pass BC5). Tier set explicitly by operator when issuing do #n; default is T2. Update ProposalReviewFlowPolicy.md.", "plan_path": "", "walkthrough_path": "", "dates": {"created": "2026-10-13 18:52:00", "suggested": "2026-10-13 18:52:00", "rejected": "2026-10-13 18:02:08"}, "state_history": [{"state": "suggested", "timestamp": "2026-10-13 18:52:00", "user": "Rolf", "note": "Emerged from LCM-AI alignment discussion during disaster recovery session 2026-10-13"}, {"state": "rejected", "timestamp": "2026-10-13 18:02:08", "user": "Operator Directive / Backlog Reconciliation", "note": "Superseded / obsolete conceptual proposal rejected per operator directive."}], "crp_id": "CRP-049", "cr_id": "CRP-049", "progress_state": "rejected", "priority": 0, "lcm_version": "Legacy (<10.0)"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (50, 'CRP-050', 'Legacy (<10.0)', 'rejected', 'rejected', 0, '.agents/rules', 'Formalize HaSSD06 Subsystem BC5 Exemption in ReviewCommitGovernancePolicy.md', 'The HaSSD06 and HaSSD06_Inventory subsystem BC5 review-gate exemption is currently documented only in ACTIVE_CONTEXT.md - an informal context document, not an authoritative rule file. Codify this exemption formally in ReviewCommitGovernancePolicy.md (RULE-REV-001) as a named exception alongside the LCM_Inventory data exemption. Prevents a future agent loading only rule files from incorrectly applying the BC5 gate to HA subsystem changes.', 'Rolf', '2026-10-13 18:52:00', '', '', '', 'standard', 0, 1, '{"id": 50, "timestamp": "2026-10-13 18:52:00", "title": "Formalize HaSSD06 Subsystem BC5 Exemption in ReviewCommitGovernancePolicy.md", "origin_repo": ".agents/rules", "state": "rejected", "bundle_id": "unassigned", "author": "Rolf", "details": "The HaSSD06 and HaSSD06_Inventory subsystem BC5 review-gate exemption is currently documented only in ACTIVE_CONTEXT.md - an informal context document, not an authoritative rule file. Codify this exemption formally in ReviewCommitGovernancePolicy.md (RULE-REV-001) as a named exception alongside the LCM_Inventory data exemption. Prevents a future agent loading only rule files from incorrectly applying the BC5 gate to HA subsystem changes.", "plan_path": "", "walkthrough_path": "", "dates": {"created": "2026-10-13 18:52:00", "suggested": "2026-10-13 18:52:00", "rejected": "2026-10-13 18:02:08"}, "state_history": [{"state": "suggested", "timestamp": "2026-10-13 18:52:00", "user": "Rolf", "note": "Identified as governance gap during LCM-AI alignment analysis 2026-10-13"}, {"state": "rejected", "timestamp": "2026-10-13 18:02:08", "user": "Operator Directive / Backlog Reconciliation", "note": "Superseded / obsolete conceptual proposal rejected per operator directive."}], "crp_id": "CRP-050", "cr_id": "CRP-050", "progress_state": "rejected", "priority": 0, "lcm_version": "Legacy (<10.0)"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (51, 'CRP-051', 'Legacy (<10.0)', 'rejected', 'rejected', 0, '.agents/rules / LCM_AI', 'Formalize implementation_plan.md as Mandatory CRP Sub-Artifact for T2 and T3 Proposals', 'Define implementation_plan.md as a required sub-artifact of every T2 and T3 CRP, referenced via the existing plan_path field in proposals.json. The implementation_plan addresses HOW to reach the goal (distinct from Architecture=WHAT and Implementation=CODE). Authored after CRM acceptance, before implementation begins, leading directly to the Implementation stage. Supersedes IDE-native planning artifacts for LCM-governed work. Update ProposalReviewFlowPolicy.md and DocumentationStandardsPolicy.md.', 'Rolf', '2026-10-13 18:52:00', '', '', '', 'standard', 0, 1, '{"id": 51, "timestamp": "2026-10-13 18:52:00", "title": "Formalize implementation_plan.md as Mandatory CRP Sub-Artifact for T2 and T3 Proposals", "origin_repo": ".agents/rules / LCM_AI", "state": "rejected", "bundle_id": "unassigned", "author": "Rolf", "details": "Define implementation_plan.md as a required sub-artifact of every T2 and T3 CRP, referenced via the existing plan_path field in proposals.json. The implementation_plan addresses HOW to reach the goal (distinct from Architecture=WHAT and Implementation=CODE). Authored after CRM acceptance, before implementation begins, leading directly to the Implementation stage. Supersedes IDE-native planning artifacts for LCM-governed work. Update ProposalReviewFlowPolicy.md and DocumentationStandardsPolicy.md.", "plan_path": "", "walkthrough_path": "", "dates": {"created": "2026-10-13 18:52:00", "suggested": "2026-10-13 18:52:00", "rejected": "2026-10-13 18:02:08"}, "state_history": [{"state": "suggested", "timestamp": "2026-10-13 18:52:00", "user": "Rolf", "note": "User decision: retain implementation_plan.md as formal CRP artifact; not suppressed by IDE planning mode"}, {"state": "rejected", "timestamp": "2026-10-13 18:02:08", "user": "Operator Directive / Backlog Reconciliation", "note": "Superseded / obsolete conceptual proposal rejected per operator directive."}], "crp_id": "CRP-051", "cr_id": "CRP-051", "progress_state": "rejected", "priority": 0, "lcm_version": "Legacy (<10.0)"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (52, 'CRP-052', 'Legacy (<10.0)', 'rejected', 'rejected', 0, '.agents/rules / LCM_AI', 'Bidirectional LCM Lifecycle Chain - Formal Entry-Point Governance and Bottom-Up Cycles', 'Formalize the LCM lifecycle chain as a directed graph with bidirectional edges and multiple valid entry points - not a strict top-down waterfall. Entry can occur at any node: BUG, CRP, CRM, Implementation Plan, Architecture, Requirements, Implementation, Refactor. Reviews between nodes are proportional to event tier (T0-T3). Bottom-up cycles (USE to Refactor to Requirements to CRP) are first-class and governed equivalently to top-down flows. The CM records the path actually taken. Update ProposalReviewFlowPolicy.md with formal chain diagram and entry-point rules.', 'Rolf', '2026-10-13 18:52:00', '', '', '', 'standard', 0, 1, '{"id": 52, "timestamp": "2026-10-13 18:52:00", "title": "Bidirectional LCM Lifecycle Chain - Formal Entry-Point Governance and Bottom-Up Cycles", "origin_repo": ".agents/rules / LCM_AI", "state": "rejected", "bundle_id": "unassigned", "author": "Rolf", "details": "Formalize the LCM lifecycle chain as a directed graph with bidirectional edges and multiple valid entry points - not a strict top-down waterfall. Entry can occur at any node: BUG, CRP, CRM, Implementation Plan, Architecture, Requirements, Implementation, Refactor. Reviews between nodes are proportional to event tier (T0-T3). Bottom-up cycles (USE to Refactor to Requirements to CRP) are first-class and governed equivalently to top-down flows. The CM records the path actually taken. Update ProposalReviewFlowPolicy.md with formal chain diagram and entry-point rules.", "plan_path": "", "walkthrough_path": "", "dates": {"created": "2026-10-13 18:52:00", "suggested": "2026-10-13 18:52:00", "rejected": "2026-10-13 18:02:08"}, "state_history": [{"state": "suggested", "timestamp": "2026-10-13 18:52:00", "user": "Rolf", "note": "Emerged from 60-year CS experience alignment discussion during disaster recovery session 2026-10-13"}, {"state": "rejected", "timestamp": "2026-10-13 18:02:08", "user": "Operator Directive / Backlog Reconciliation", "note": "Superseded / obsolete conceptual proposal rejected per operator directive."}], "crp_id": "CRP-052", "cr_id": "CRP-052", "progress_state": "rejected", "priority": 0, "lcm_version": "Legacy (<10.0)"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (53, 'CRP-053', 'Legacy (<10.0)', 'rejected', 'rejected', 0, '.agents/rules', 'Resolve processed State Inconsistency Between RULE-LCM-002 and RULE-LCM-007 Canonical State Enum', 'RULE-LCM-002 references a processed state after do #n command execution, but RULE-LCM-007 defines the canonical state enum as: bug | suggested | approved | deferred | rejected | completed | pushed. The term processed does not appear in the canonical enum. Determine the authoritative state name and update rule files consistently. Operator position: canonical states must not change without explicit approval - this CRP resolves the documentation inconsistency only.', 'Rolf', '2026-10-13 18:52:00', '', '', '', 'standard', 0, 1, '{"id": 53, "timestamp": "2026-10-13 18:52:00", "title": "Resolve processed State Inconsistency Between RULE-LCM-002 and RULE-LCM-007 Canonical State Enum", "origin_repo": ".agents/rules", "state": "rejected", "bundle_id": "unassigned", "author": "Rolf", "details": "RULE-LCM-002 references a processed state after do #n command execution, but RULE-LCM-007 defines the canonical state enum as: bug | suggested | approved | deferred | rejected | completed | pushed. The term processed does not appear in the canonical enum. Determine the authoritative state name and update rule files consistently. Operator position: canonical states must not change without explicit approval - this CRP resolves the documentation inconsistency only.", "plan_path": "", "walkthrough_path": "", "dates": {"created": "2026-10-13 18:52:00", "suggested": "2026-10-13 18:52:00", "rejected": "2026-10-13 18:02:08"}, "state_history": [{"state": "suggested", "timestamp": "2026-10-13 18:52:00", "user": "Rolf", "note": "Identified as rule taxonomy inconsistency during LCM-AI alignment analysis 2026-10-13"}, {"state": "rejected", "timestamp": "2026-10-13 18:02:08", "user": "Operator Directive / Backlog Reconciliation", "note": "Superseded / obsolete conceptual proposal rejected per operator directive."}], "crp_id": "CRP-053", "cr_id": "CRP-053", "progress_state": "rejected", "priority": 0, "lcm_version": "Legacy (<10.0)"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (54, 'CRP-054', 'Legacy (<10.0)', 'pushed', 'pushed', 0, 'LCM_Inventory', 'Clarify LCM_Inventory Tool Governance Scope - Privileged Subsystem Not Exempt from Tool Scrutiny', 'Clarify in RULE-LCM-004 that LCM_Inventory is a privileged subsystem whose configuration data (inventory.json, dashboards, baselines, logs) is auto-accepted per RULE-EFF-001, but whose tool source code (tools/*.ps1, modules/*.psm1, docs/*.md) is subject to full LCM governance including BC5 review gates and semantic versioning. Current rule language implies entire WI repo is BC5-exempt. Update RULE-LCM-004 to distinguish WI data exemption from WI tool governance scope.', 'Rolf', '2026-10-13 18:52:00', '2026-10-13 22:38:53', '', '', 'standard', 0, 1, '{"id": 54, "timestamp": "2026-10-13 18:52:00", "title": "Clarify LCM_Inventory Tool Governance Scope - Privileged Subsystem Not Exempt from Tool Scrutiny", "origin_repo": "LCM_Inventory", "state": "pushed", "progress_state": "pushed", "bundle_id": "CRP-054", "author": "Rolf", "details": "Clarify in RULE-LCM-004 that LCM_Inventory is a privileged subsystem whose configuration data (inventory.json, dashboards, baselines, logs) is auto-accepted per RULE-EFF-001, but whose tool source code (tools/*.ps1, modules/*.psm1, docs/*.md) is subject to full LCM governance including BC5 review gates and semantic versioning. Current rule language implies entire WI repo is BC5-exempt. Update RULE-LCM-004 to distinguish WI data exemption from WI tool governance scope.", "plan_path": "LCM_Inventory/docs/Proposals/CRP-054-LCM-10.0.0-Workspace-Inventory-Tool-Governance-Scope-And-Data-Exemption-Split.md", "walkthrough_path": "", "dates": {"created": "2026-10-13 18:52:00", "suggested": "2026-10-13 18:52:00", "in_progress": "2026-10-13 14:18:00", "completed": "2026-10-13 14:26:00", "pushed": "2026-10-13 22:38:53"}, "state_history": [{"state": "suggested", "timestamp": "2026-10-13 18:52:00", "user": "Rolf", "note": "Operator resolved Q3: WI tools are fully LCM-governed; rule must reflect this explicitly"}, {"state": "in_progress", "timestamp": "2026-10-13 14:18:00", "user": "Rolf", "note": "Implementation initiated per operator directive"}, {"state": "completed", "timestamp": "2026-10-13 14:26:00", "user": "Rolf", "note": "Operator visual review disposition ACCEPT ALL"}, {"state": "pushed", "timestamp": "2026-10-13 22:38:53", "user": "rgbig", "note": "Pushed to remote (Git_Repositories, LCM_AI, LCM_Inventory)"}], "crp_id": "CRP-054", "cr_id": "CRP-054", "pushed_at": "2026-10-13 22:38:53", "priority": 0, "lcm_version": "Legacy (<10.0)"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (55, 'CRP-055', 'Legacy (<10.0)', 'pushed', 'pushed', 0, '.agents/rules', 'Close RULE-LCM-013 Gap - Extend Pre-Push Gemini Sync to Single-Repo Direct Pushes', 'RULE-LCM-013 mandates Update-Gemini.ps1 before every multi-repository push via Invoke-WorkspacePush.ps1, but does not address single-repository direct pushes. An agent or developer could push a single repo without triggering the GDrive sync. Extend RULE-LCM-013 to either: (a) mandate Update-Gemini.ps1 before any push regardless of scope, or (b) explicitly document the acceptable exception scope and its conditions.', 'Rolf', '2026-10-13 18:52:00', '2026-10-13 14:10:00', '', '', 'standard', 0, 1, '{"id": 55, "timestamp": "2026-10-13 18:52:00", "title": "Close RULE-LCM-013 Gap - Extend Pre-Push Gemini Sync to Single-Repo Direct Pushes", "origin_repo": ".agents/rules", "state": "pushed", "progress_state": "pushed", "bundle_id": "unassigned", "author": "Rolf", "details": "RULE-LCM-013 mandates Update-Gemini.ps1 before every multi-repository push via Invoke-WorkspacePush.ps1, but does not address single-repository direct pushes. An agent or developer could push a single repo without triggering the GDrive sync. Extend RULE-LCM-013 to either: (a) mandate Update-Gemini.ps1 before any push regardless of scope, or (b) explicitly document the acceptable exception scope and its conditions.", "plan_path": "", "walkthrough_path": "", "dates": {"created": "2026-10-13 18:52:00", "suggested": "2026-10-13 18:52:00", "completed": "2026-10-13 14:10:00", "pushed": "2026-10-13 14:10:00"}, "state_history": [{"state": "suggested", "timestamp": "2026-10-13 18:52:00", "user": "Rolf", "note": "Identified as governance gap during LCM-AI alignment analysis 2026-10-13"}, {"state": "completed", "timestamp": "2026-10-13 14:10:00", "user": "Operator ACCEPTED / Governance Alignment", "note": "Amended RULE-LCM-013 in ProposalReviewFlowPolicy.md to mandate Update-Gemini.ps1 for both multi-repository and single-repository pushes (-Repositories <repo>). Direct un-synced manual git push prohibited."}, {"state": "pushed", "timestamp": "2026-10-13 14:10:00", "user": "rgbig", "note": "Rule codified and synchronized across LCM repository."}], "crp_id": "CRP-055", "cr_id": "CRP-055", "pushed_at": "2026-10-13 14:10:00", "priority": 0, "lcm_version": "Legacy (<10.0)"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (56, 'CRP-056', 'Legacy (<10.0)', 'rejected', 'rejected', 0, 'LCM_Inventory', 'Autonomous Loop-Fencing, Execution Boundaries, and T0 State Recovery Engine', '1. PreToolUse turn fence (15 turns default, operator extendable) + loop hash detection. 2. Local-scratch lease tracking (OneDrive sync isolated). 3. Atomic serialization for proposals.json ([System.IO.File]::Replace). 4. T0 watchdog and automatic transition to ''blocked'' upon orphaned lease detection. 5. Windows Task governance: all Windows Tasks created by LCM_Backup (events, tool communication) must be registered and governed via LCM_Supervision.', 'Technical Engineering & Governance Team', '2026-10-13 20:16:00', '', '', '', 'standard', 0, 1, '{"id": 56, "timestamp": "2026-10-13 20:16:00", "title": "Autonomous Loop-Fencing, Execution Boundaries, and T0 State Recovery Engine", "origin_repo": "LCM_Inventory", "state": "rejected", "bundle_id": "unassigned", "author": "Technical Engineering & Governance Team", "tier": "T2", "details": "1. PreToolUse turn fence (15 turns default, operator extendable) + loop hash detection. 2. Local-scratch lease tracking (OneDrive sync isolated). 3. Atomic serialization for proposals.json ([System.IO.File]::Replace). 4. T0 watchdog and automatic transition to ''blocked'' upon orphaned lease detection. 5. Windows Task governance: all Windows Tasks created by LCM_Backup (events, tool communication) must be registered and governed via LCM_Supervision.", "plan_path": "LCM_Inventory/data/proposals/plans/Proposal-056_CRP-2026-031_Plan.md", "walkthrough_path": "LCM_Inventory/data/proposals/plans/Proposal-056_CRP-2026-031_Walkthrough.md", "dates": {"created": "2026-10-13 20:16:00", "suggested": "2026-10-13 20:16:00", "approved": "2026-10-13 20:39:05", "in_progress": "2026-10-13 20:56:55", "rejected": "2026-10-13 18:02:08"}, "state_history": [{"state": "suggested", "timestamp": "2026-10-13 20:16:00", "user": "Technical Engineering & Governance Team", "note": "Registered as T2 standard architecture proposal with queued progress state"}, {"state": "approved", "timestamp": "2026-10-13 20:39:05", "user": "Rolf", "note": "CRM Gate Accepted. Privileged subsystem ''LCM Backup'' scope established; implementation plan authorized."}, {"state": "approved", "progress_state": "in_progress", "timestamp": "2026-10-13 20:56:55", "user": "Rolf", "note": "Authorized Phase 1 execution (Subsystem Scaffold & Tool Integration) via do #56 directive."}, {"state": "approved", "progress_state": "in_progress", "timestamp": "2026-10-13 11:05:45", "user": "Rolf", "note": "Amended requirement: Windows Tasks created by LCM_Backup (events, tool communication) must be governed via LCM_Supervision."}, {"state": "rejected", "timestamp": "2026-10-13 18:02:08", "user": "Operator Directive / Backlog Reconciliation", "note": "Superseded / obsolete conceptual proposal rejected per operator directive."}], "crp_id": "CRP-056", "cr_id": "CRP-056", "progress_state": "rejected", "priority": 0, "lcm_version": "Legacy (<10.0)"}');
