INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (81, 'CRP-081', 'Legacy (<10.0)', 'pushed', 'pushed', 0, 'LCM_AI / LCM_Inventory', 'Design and Implement LCM Universal Installation Path, Packaging Agent, Preflight Engine, and UX Verification Suite', 'Comprehensive design and implementation of the LCM Installation Path: payload extraction from LCM workspace (excluding subsystems), analogous subsystem install contract, configurable target root directory structure, Setup packaging agent, interactive Pre-Installation Check Tool with unified completion log, separate Onboarding function, and post-installation UX verification tool. (Re-instated as CRP-081 with verified final state ''pushed'' from historical #12 / CR-2026-023).', 'rgbig', '2026-10-13 18:34:51', '2026-10-13 15:29:48', '', '', 'standard', 0, 1, '{"id": 81, "crp_id": "CRP-081", "timestamp": "2026-10-13 23:09:10", "title": "Design and Implement LCM Universal Installation Path, Packaging Agent, Preflight Engine, and UX Verification Suite", "origin_repo": "LCM_AI / LCM_Inventory", "cr_id": "CRP-081", "bundle_id": "CRP-081", "state": "pushed", "progress_state": "pushed", "author": "rgbig", "details": "Comprehensive design and implementation of the LCM Installation Path: payload extraction from LCM workspace (excluding subsystems), analogous subsystem install contract, configurable target root directory structure, Setup packaging agent, interactive Pre-Installation Check Tool with unified completion log, separate Onboarding function, and post-installation UX verification tool. (Re-instated as CRP-081 with verified final state ''pushed'' from historical #12 / CR-2026-023).", "plan_path": "LCM_Inventory/data/proposals/plans/Proposal-012_CR-2026-023_Plan.md", "walkthrough_path": "LCM_Inventory/data/proposals/plans/Proposal-012_CR-2026-023_Walkthrough