INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (132, 'CRP-132', '10.0.0', 'pushed', 'pushed', 0, 'LCM / Git_Repositories', 'Git-Root Directory Structure Cleanup, De-Duplication, and Hub/Hooks Rationalization', 'Clean up and rationalize Git-Root .lcm directory structure following tool migration to LCM_Inventory: eliminate duplicate hooks directories (LCM_Inventory/hooks vs LCM_Inventory/tools/hooks), de-duplicate hub infrastructure (LCM_Inventory/tools/hub vs LCM_Inventory), and re-architect the misplaced LCM_Inventory/tools/internal hierarchy safely without breaking desktop shortcuts or daemons.', 'Operator Directive / CRP Intake', '2026-10-13 22:09:00', '2026-10-13 18:05:33', '', '', 'standard', 0, 1, '{"id": 132, "timestamp": "2026-10-13 22:09:00", "title": "Git-Root Directory Structure Cleanup, De-Duplication, and Hub/Hooks Rationalization", "origin_repo": "LCM / Git_Repositories", "state": "pushed", "progress_state": "pushed", "bundle_id": "CRP-132", "author": "Operator Directive / CRP Intake", "details": "Clean up and rationalize Git-Root .lcm directory structure following tool migration to LCM_Inventory: eliminate duplicate hooks directories (LCM_Inventory/hooks vs LCM_Inventory/tools/hooks), de-duplicate hub infrastructure (LCM_Inventory/tools/hub vs LCM_Inventory), and re-architect the misplaced LCM_Inventory/tools/internal hierarchy safely without breaking desktop shortcuts or daemons.", "plan_path": "LCM_Inventory/docs/Proposals/CRP-132-LCM-10.0.0-Git-Root-Directory-Structure-Cleanup-And-De-Duplication.md", "walkthrough_path": "", "dates": {"created": "2026-10-13 22:09:00", "suggested": "2026-10-13 22:09:00", "completed": "2026-10-13 18:02:08", "pushed": "2026-10-13 18:05:33"}, "state_history": [{"state": "suggested", "timestamp": "2026-10-13 22:09:00", "user": "Operator Directive / CRP