INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (221, 'CRP-221', '10.1.0', 'pushed', 'pushed', 0, 'LCM_AI', 'Distinguish Cancelled vs Rejected & Preserve Baseline Scratchpad Timestamps', 'Codify distinction between Cancelled (administrative withdrawal at Gate 1 without code reverts) and Rejected (implementation rejection at Gate 2 with active rollback to pre-CRP baseline) in RULE-LCM-002/007, preserve historical file timestamps on review scratchpads (BCompareBaseline/CompactBCompareReview), and enforce single-tab idempotency in BCR.', 'rgbig', '2026-10-13 19:15:58', '2026-11-06 10:44:45', 'docs/Proposals/CRP-221-Distinguish-Cancelled-vs-Rejected-in-ProposalRevie', 'completed', 'doit', 0, 1, '{"id": 221, "crp_id": "CRP-221", "timestamp": "2026-10-13 19:15:58", "title": "Distinguish Cancelled vs Rejected & Preserve Baseline Scratchpad Timestamps", "origin_repo": "LCM_AI", "cr_id": "CRP-221", "app_id": null, "primary_app": null, "affected_apps": null, "state": "pushed", "flow_mode": "doit", "always_proceed": true, "bundle_id": "unassigned", "bundle_dir": "docs/Proposals/CRP-221-Distinguish-Cancelled-vs-Rejected-in-ProposalRevie", "docs": {"specification": "Specification.md", "plan": "Implementation_Plan.md", "walkthrough": "Walkthrough.md"}, "commit_sha": null, "github_url": null, "author": "rgbig", "details": "Codify distinction between Cancelled (administrative withdrawal at Gate 1 without code reverts) and Rejected (implementation rejection at Gate 2 with active rollback to pre-CRP baseline) in RULE-LCM-002/007, preserve historical file timestamps on review scratchpads (BCompareBaseline/CompactBCompareReview), and enforce single-tab idempotency in BCR.", "plan_path": "docs/Proposals/CRP-221-Distinguish-Cancelled-vs-Rejected-in-ProposalRevie/Implementation_Plan.md", "walkthrough_path": "docs/Proposals/CRP-221-Distinguish-Cancelled-vs-Rejected-in-ProposalRevie/Walkthrough.md", "progress_state": "pushed", "disposition": "completed", "priority": 0, "pushed_at": "2026-11-06 10:44:45", "lcm_version": "10.1.0"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (243, 'CRP-243', '10.1.0', 'pushed', 'pushed', 0, 'LCM_AI', 'Integration of Read-Only Analysis Protocol & Implementation Gating into Workspace Governance', 'Establishes a formal, model-first analysis lifecycle across all workspace AI interactions (specifically Antigravity IDE and Gemini sessions). This proposal introduces strict modal separation between READ-ONLY ANALYSIS and GOVERNED IMPLEMENTATION, enforced via intent wake words (ANALYZE / IMPLEMENT), verifiable provenance tagging, and explicit human-in-the-loop decision gates. Surfaces runtime state transparency variables (LCM_OperatingMode, LCM_ActiveGate, LCM_SearchRadius, LCM_SettledFacts, LCM_OpenHypotheses, LCM_CircuitBreaker) to LCM Control Hub.', 'rgbig', '2026-10-13 15:43:18', '2026-11-06 10:44:45', 'docs/Proposals/CRP-243-Integration-of-Read-Only-Analysis-Protocol-Impleme', '', 'standard', 0, 1, '{"id": 243, "crp_id": "CRP-243", "timestamp": "2026-10-13 15:43:18", "title": "Integration of Read-Only Analysis Protocol & Implementation Gating into Workspace Governance", "origin_repo": "LCM_AI", "cr_id": "CRP-2026-005", "app_id": null, "primary_app": null, "affected_apps": null, "state": "pushed", "bundle_id": "unassigned", "bundle_dir": "docs/Proposals/CRP-243-Integration-of-Read-Only-Analysis-Protocol-Impleme", "docs": {"specification": "Specification.md", "plan": "Implementation_Plan.md", "walkthrough": "Walkthrough.md"}, "commit_sha": null, "github_url": null, "author": "rgbig", "details": "Establishes a formal, model-first analysis lifecycle across all workspace AI interactions (specifically Antigravity IDE and Gemini sessions). This proposal introduces strict modal separation between READ-ONLY ANALYSIS and GOVERNED IMPLEMENTATION, enforced via intent wake words (ANALYZE / IMPLEMENT), verifiable provenance tagging, and explicit human-in-the-loop decision gates. Surfaces runtime state transparency variables (LCM_OperatingMode, LCM_ActiveGate, LCM_SearchRadius, LCM_SettledFacts, LCM_OpenHypotheses, LCM_CircuitBreaker) to LCM Control Hub.", "plan_path": "docs/Proposals/CRP-243-Integration-of-Read-Only-Analysis-Protocol-Impleme/Implementation_Plan.md", "walkthrough_path": "docs/Proposals/CRP-243-Integration-of-Read-Only-Analysis-Protocol-Impleme/Walkthrough.md", "progress_state": "pushed", "priority": 0, "pushed_at": "2026-11-06 10:44:45", "lcm_version": "10.1.0"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (244, 'CRP-244', '10.1.0', 'superseded', 'deferred', 5, 'LCM_AI', 'WHAT-IF Analysis Sub-Path Protocol and Trial Implementation Branching', 'Enables a formal WHAT-IF exploratory sub-path within ANALYSIS mode when a CRP is unfinalized, blocked, or encounters architectural hurdles. Allows operators and agents to formulate alternative trial hypotheses, execute an isolated trial implementation branch with rollback checkpoints, and evaluate it at review. If accepted at review, the trial is promoted; if rejected, the pre-trial baseline state is cleanly restored and the session drops back into Analysis mode for alternative exploration.', 'rgbig', '2026-10-13 16:06:20', '', 'docs/Proposals/CRP-244-WHAT-IF-Analysis-Sub-Path-Protocol-and-Trial-Imple', 'superseded', 'standard', 0, 1, '{"id": 244, "crp_id": "CRP-244", "timestamp": "2026-10-13 16:06:20", "title": "WHAT-IF Analysis Sub-Path Protocol and Trial Implementation Branching", "origin_repo": "LCM_AI", "cr_id": "CRP-244", "app_id": null, "primary_app": null, "affected_apps": null, "state": "superseded", "bundle_id": "unassigned", "bundle_dir": "docs/Proposals/CRP-244-WHAT-IF-Analysis-Sub-Path-Protocol-and-Trial-Imple", "docs": {"specification": "Specification.md", "plan": "Implementation_Plan.md", "walkthrough": "Walkthrough.md"}, "commit_sha": null, "github_url": null, "author": "rgbig", "details": "Enables a formal WHAT-IF exploratory sub-path within ANALYSIS mode when a CRP is unfinalized, blocked, or encounters architectural hurdles. Allows operators and agents to formulate alternative trial hypotheses, execute an isolated trial implementation branch with rollback checkpoints, and evaluate it at review. If accepted at review, the trial is promoted; if rejected, the pre-trial baseline state is cleanly restored and the session drops back into Analysis mode for alternative exploration.", "plan_path": "docs/Proposals/CRP-244-WHAT-IF-Analysis-Sub-Path-Protocol-and-Trial-Imple/Implementation_Plan.md", "walkthrough_path": "docs/Proposals/CRP-244-WHAT-IF-Analysis-Sub-Path-Protocol-and-Trial-Imple/Walkthrough.md", "priority": 5, "progress_state": "deferred", "disposition": "superseded", "state_history": [{"from_state": "suggested", "state": "superseded", "timestamp": "2026-10-16 20:56:10", "user": "rgbig", "note": "CRP-251 provides the stronger disposable-sandbox and explicit-promotion design for CRP-244''s WHAT-IF trial goal; CRP-244 had no implementation.", "cohort_id": "", "cohort_gate": "", "synchronization_outcome": ""}], "dates": {"superseded": "2026-10-16 20:56:10"}, "superseded_by_id": 251, "superseded_at": "2026-10-16 20:56:10", "lcm_version": "10.1.0"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (245, 'BUG-245', '10.2.0', 'pushed', 'pushed', 0, 'LCM_Inventory', 'BCR Foreground Console Window Hygiene and Premature Review Scratchpad Purge', 'Addresses two Beyond Compare Review (BCR) runtime defects: (1) A visible PowerShell console window pops up in the foreground when BCR is dispatched via the daemon and is left lingering/unclosed; (2) Premature purging of the BC review scratchpad (scratch\BC_Review\CRP-nnn) during Submit-ReviewResult causes Beyond Compare fast-refresh errors (path not found) while BC sessions are still open or other repos in the multi-repo CRP are being reviewed.', 'rgbig', '2026-10-13 16:22:24', '2026-11-06 10:44:45', 'docs/Proposals/BUG-245-BCR-Foreground-Console-Window-Hygiene-and-Prematur', '', 'standard', 0, 0, '{"id": 245, "crp_id": "BUG-245", "timestamp": "2026-10-13 16:22:24", "title": "BCR Foreground Console Window Hygiene and Premature Review Scratchpad Purge", "origin_repo": "LCM_Inventory", "cr_id": "BUG-245", "app_id": null, "primary_app": null, "affected_apps": null, "state": "pushed", "bundle_id": "unassigned", "bundle_dir": "docs/Proposals/BUG-245-BCR-Foreground-Console-Window-Hygiene-and-Prematur", "docs": {"specification": "Specification.md", "plan": "Implementation_Plan.md", "walkthrough": "Walkthrough.md"}, "commit_sha": null, "github_url": null, "author": "rgbig", "details": "Addresses two Beyond Compare Review (BCR) runtime defects: (1) A visible PowerShell console window pops up in the foreground when BCR is dispatched via the daemon and is left lingering/unclosed; (2) Premature purging of the BC review scratchpad (scratch\\BC_Review\\CRP-nnn) during Submit-ReviewResult causes Beyond Compare fast-refresh errors (path not found) while BC sessions are still open or other repos in the multi-repo CRP are being reviewed.", "plan_path": "docs/Proposals/BUG-245-BCR-Foreground-Console-Window-Hygiene-and-Prematur/Implementation_Plan.md", "walkthrough_path": "docs/Proposals/BUG-245-BCR-Foreground-Console-Window-Hygiene-and-Prematur/Walkthrough.md", "progress_state": "pushed", "priority": 0, "pushed_at": "2026-11-06 10:44:45", "lcm_version": "10.2.0"}');
INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (246, 'CRP-246', '10.1.0', 'pushed', 'pushed', 0, 'LCM_Inventory', 'Consolidate Canonical Rules in LCM_AI and Migrate Root .lcm Subsystem to LCM_Inventory', 'Consolidates all canonical LCM governance rules into a single authoritative folder in LCM_AI (.agents\rules) and eliminates local variants and redundant sub-junctions where higher-up junctions exist. Migrates all physical code, PowerShell modules (LcmDaemon), desktop services (LcmDesktopDaemon), command wrappers, and tools from D:\Git_Repositories\.lcm into LCM_Inventory, updating system registry startup and PATH. Establishes cross-repo linkage rather than code duplication, and cleans root Git_Repositories to a lightweight governance container.', 'rgbig', '2026-10-13 16:55:00', '2026-11-06 10:21:10', 'docs/Proposals/CRP-246-Consolidate-Rules-in-LCM_AI-and-Migrate-Root-lcm-to-LCM_Inventory', '', 'doit', 0, 1, '{"id": 246, "crp_id": "CRP-246", "timestamp": "2026-10-13 16:55:00", "title": "Consolidate Canonical Rules in LCM_AI and Migrate Root .lcm Subsystem to LCM_Inventory", "origin_repo": "LCM_Inventory", "cr_id": "CRP-246", "app_id": null, "primary_app": null, "affected_apps": null, "state": "pushed", "bundle_id": "unassigned", "bundle_dir": "docs/Proposals/CRP-246-Consolidate-Rules-in-LCM_AI-and-Migrate-Root-lcm-to-LCM_Inventory", "docs": {"specification": "Specification.md", "plan": "Implementation_Plan.md", "walkthrough": "Walkthrough.md"}, "commit_sha": null, "github_url": null, "author": "rgbig", "details": "Consolidates all canonical LCM governance rules into a single authoritative folder in LCM_AI (.agents\\rules) and eliminates local variants and redundant sub-junctions where higher-up junctions exist. Migrates all physical code, PowerShell modules (LcmDaemon), desktop services (LcmDesktopDaemon), command wrappers, and tools from D:\\Git_Repositories\\.lcm into LCM_Inventory, updating system registry startup and PATH. Establishes cross-repo linkage rather than code duplication, and cleans root Git_Repositories to a lightweight governance container.", "plan_path": "docs/Proposals/CRP-246-Consolidate-Rules-in-LCM_AI-and-Migrate-Root-lcm-to-LCM_Inventory/Implementation_Plan.md", "walkthrough_path": "docs/Proposals/CRP-246-Consolidate-Rules-in-LCM_AI-and-Migrate-Root-lcm-to-LCM_Inventory/Walkthrough.md", "flow_mode": "doit", "always_proceed": true, "progress_state": "pushed", "priority": 0, "pushed_at": "2026-11-06 10:21:10", "lcm_version": "10.1.0"}');
