INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (286, 'BUG-286', '10.2.0', 'pushed', 'pushed', 0, 'LCM_Inventory', '[BUG] Control Hub daemon outage capture and automatic recovery', 'When the Control Hub daemon listener on port 9876 is unavailable, the condition must be durably recorded and a bounded automatic recovery attempt must be made before the Hub falls back to cached/local data. The operator must see the recovery outcome. This BUG also corrects the daemon status diagnostic failure when the legacy Run-key value is absent.', 'rgbig', '2026-10-17 20:33:52', '2026-11-06 10:44:45', 'docs/Proposals/BUG-286-BUG-Control-Hub-daemon-outage-capture-and-automati', 'completed', 'doit', 0, 0, '{"id": 286, "crp_id": "BUG-286", "timestamp": "2026-10-17 20:33:52", "title": "[BUG] Control Hub daemon outage capture and automatic recovery", "origin_repo": "LCM_Inventory", "cr_id": "BUG-286", "app_id": null, "primary_app": "LCM Control Hub", "affected_apps": "LCM Control Hub", "state": "pushed", "bundle_id": "unassigned", "bundle_dir": "docs/Proposals/BUG-286-BUG-Control-Hub-daemon-outage-capture-and-automati", "docs": {"specification": "Specification.md", "plan": "Implementation_Plan.md", "walkthrough": "Walkthrough.md"}, "commit_sha": null, "github_url": null, "author": "rgbig", "details": "When the Control Hub daemon listener on port 9876 is unavailable, the condition must be durably recorded and a bounded automatic recovery attempt must be made before the Hub falls back to cached/local data. The operator must see the recovery outcome. This BUG also corrects the daemon status diagnostic failure when the legacy Run-key value is absent.", "flow_mode": "doit", "always_proceed": true, "plan_path": "docs/Proposals/BUG-286-BUG-Control-Hub-daemon-outage-capture-and-automati/Implementation_Plan.md", "walkthrough_pat