INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (289, 'BUG-289', '10.2.0', 'superseded', 'deferred', 5, 'LCM_Inventory', '[BUG] Control Hub governance switch does not reflect or apply backend state', 'The Control Hub Governance switch presents ON while the authoritative proposal ledger has lcm_mode: paused. The operator cannot tell whether a click reached the daemon, changed governance, or was ignored. Repair backend-confirmed ON/OFF feedback first; define a yellow bounded-recovery indicator only as an explicit, scoped, authorized state that retains Gate 2.', 'rgbig', '2026-10-17 22:32:48', '', 'docs/Proposals/BUG-289-BUG-Control-Hub-governance-switch-does-not-reflect', 'superseded', 'doit', 0, 0, '{"id": 289, "crp_id": "BUG-289", "timestamp": "2026-10-17 22:32:48", "title": "[BUG] Control Hub governance switch does not reflect or apply backend state", "origin_repo": "LCM_Inventory", "cr_id": "BUG-289", "app_id": null, "primary_app": null, "affected_apps": null, "state": "superseded", "bundle_id": "BUG-289", "bundle_dir": "docs/Proposals/BUG-289-BUG-Control-Hub-governance-switch-does-not-reflect", "docs": {"specification": "Specification.md", "plan": "Implementation_Plan.md", "walkthrough": "Walkthrough.md"}, "commit_sha": null, "github_url": null, "author": "rgbig", "details": "The Control Hub Governance switch presents ON while the authoritative proposal ledger has lcm_mode: paused. The operator cannot tell whether a click reached the daemon, changed governance, or was ignored. Repair backend-confirmed ON/OFF feedback first; define a yellow bounded-recovery indicator only as an explicit, scoped, authorized state that retains Gate 2.", "priority": 5, "flow_mode": "doit", "always_proceed": true, "plan_path": "docs/Proposals/BUG-289-BUG-Control-Hub-governance-switch-does-not-reflect/Implementation_