INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (299, 'BUG-299', '10.2.1', 'pushed', 'pushed', 5, 'LCM_Inventory', '[BUG] Macrium Browse Image dialog detection times out while the dialog is visible', 'Observed during the 2026-10-20 BCR baseline mount attempt: the elevated Macrium worker threw "Macrium Browse Image dialog did not become ready within 30 seconds" even though the Browse Image dialog was visibly displayed. The actual cause is unconfirmed. The reported possibilities are an insufficient readiness timeout and UI Automation detection that depends on a fixed dialog location/position. Intake only: no implementation or root-cause conclusion is authorized by this registration.', 'rgbig', '2026-10-20 20:14:33', '2026-11-06 10:44:45', 'docs/Proposals/BUG-299-BUG-Macrium-Browse-Image-dialog-detection-times-ou', 'completed', 'doit', 0, 0, '{"id": 299, "crp_id": "BUG-299", "timestamp": "2026-10-20 20:14:33", "title": "[BUG] Macrium Browse Image dialog detection times out while the dialog is visible", "origin_repo": "LCM_Inventory", "cr_id": "BUG-299", "app_id": null, "primary_app": null, "affected_apps": null, "state": "pushed", "bundle_id": "unassigned", "bundle_dir": "docs/Proposals/BUG-299-BUG-Macrium-Browse-Image-dialog-detection-times-ou", "docs": {"specification": "Specification.md", "plan": "Implementation_Plan.md", "walkthrough": "Walkthrough.md"}, "commit_sha": null, "github_url": null, "author": "rgbig", "details": "Observed during the 2026-10-20 BCR baseline mount attempt: the elevated Macrium worker threw \"Macrium Browse Image dialog did not become ready within 30 seconds\" even though the Browse Image dialog was visibly displayed. The actual cause is unconfirmed. The reported possibilities are an insufficient readiness timeout and UI Automation detection that depends on a fixed dialog location/position. Intake only: no implementation or root-cause conclusion is authorized by this registration.", "priority": 5, "plan_path": "docs/Proposals/BUG-299-BUG-Macrium-Browse-Image-dialog-detection-times-ou/Implementation_Plan.md", "walkthrough_path": "docs/Proposals/BUG-299-BUG-Macrium-Browse-Image-dialog-detection-times-ou/Walkthrough.md", "state_history": [{"from_state": "suggested", "state": "in_progress", "timestamp": "2026-10-21 13:39:57", "user": "rgbig", "note": "", "cohort_id": "", "cohort_gate": "", "synchronization_outcome": ""}, {"from_state": "in_progress", "state": "verified", "timestamp": "2026-10-21 13:43:57", "user": "rgbig", "note": "", "cohort_id": "", "cohort_gate": "", "synchronization_outcome": ""}, {"from_state": "verified", "state": "in_review", "timestamp": "2026-10-21 13:44:04", "user": "rgbig", "note": "DOIT operator directive Fix-299", "cohort_id": "", "cohort_gate": "", "synchronization_outcome": ""}, {"from_state": "in_review", "state": "completed", "timestamp": "2026-10-21 13:44:14", "user": "rgbig", "note": "Review completed and committed (8417d22).", "cohort_id": "", "cohort_gate": "", "synchronization_outcome": ""}], "dates": {"in_progress": "2026-10-21 13:39:57", "verified": "2026-10-21 13:43:57", "in_review": "2026-10-21 13:44:04", "completed": "2026-10-21 13:44:14"}, "flow_mode": "doit", "always_proceed": true, "bcr_disposition": "Completed", "bcr_disposition_at": "2026-10-21 13:44:14", "bcr_disposition_notes": "DOIT Fix-299: bind dialog and detach deadlines to MountTimeoutSeconds, fallback to existing ReflectBin PIDs, and expand BC window detection to 60s", "progress_state": "pushed", "disposition": "completed", "pushed_at": "2026-11-06 10:44:45", "lcm_version": "10.2.1"}');
