INSERT INTO proposals (id, crp_id, lcm_version, state, progress_state, priority, origin_repo, title, details, author, created_at, pushed_at, bundle_dir, disposition, flow_mode, is_active, is_historical, raw_json) VALUES (303, 'CRP-303', '10.2.1', 'pushed', 'pushed', 5, 'LCM_Inventory', 'Unified session error catalog and lifecycle action diagnostics', 'Reconstruct an evidence-based, active-host-specific failure-mode report from the historical catalog. Accept a bare item number or quoted conversation anchor, default to the last referenced item, combine read-only lifecycle diagnostics and Show-Actions output, and write a timestamped sibling report identifying generator name/version and including a Summary. Preserve original catalog and all lifecycle state.', 'Rolf, Copilot', '2026-10-21 18:28:34', '2026-11-06 10:44:45', 'docs/Proposals/CRP-303-Unified-session-error-catalog-and-lifecycle-action', 'completed', 'doit', 0, 0, '{"id": 303, "crp_id": "CRP-303", "timestamp": "2026-10-21 18:28:34", "title": "Unified session error catalog and lifecycle action diagnostics", "origin_repo": "LCM_Inventory", "cr_id": "CRP-303", "app_id": null, "primary_app": null, "affected_apps": null, "state": "pushed", "bundle_id": "unassigned", "bundle_dir": "docs/Proposals/CRP-303-Unified-session-error-catalog-and-lifecycle-action", "docs": {"specification": "Specification.md", "plan": "Implementation_Plan.md", "walkthrough": "Walkthrough.md"}, "commit_sha": null, "github_url": null, "author": "Rolf, Copilot", "details": "Reconstruct an evidence-based, active-host-specific failure-mode report from the historical catalog. Accept a bare item number or quoted conversation anchor, default to the last referenced item, combine read-only lifecycle diagnostics and Show-Actions output, and write a timestamped sibling report identifying generator name/version and including a Summary. Preserve original catalog and all lifecycle state.", "priority": 5, "plan_path": "docs/Proposals/CRP-303-Unified-session-