CREATE TABLE IF NOT EXISTS _lcm_db_metadata (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS proposals (
    id INTEGER PRIMARY KEY,
    crp_id TEXT NOT NULL UNIQUE,
    lcm_version TEXT NOT NULL,
    state TEXT NOT NULL,
