    pushed_at TEXT,
    bundle_dir TEXT,
    disposition TEXT,
    flow_mode TEXT,
    is_active INTEGER DEFAULT 0,
    is_historical INTEGER DEFAULT 0,
    raw_json TEXT NOT NULL
);

