CREATE INDEX IF NOT EXISTS idx_proposals_priority ON proposals(priority);
CREATE INDEX IF NOT EXISTS idx_proposals_origin_repo ON proposals(origin_repo);

DELETE FROM _lcm_db_metadata;

DELETE FROM proposals;

